import time
from functools import wraps
from collections import OrderedDict

class TTLCache:
    def __init__(self, maxsize: int, ttl: int, timer: Callable[[], float], typed: bool):
        self.cache = OrderedDict()
        self.maxsize = maxsize
        self.ttl = ttl
        self.timer = timer
        self.typed = typed

    def __call__(self, func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))
            if key in self.cache:
                obj, timestamp = self.cache[key]
                if self.timer() - timestamp < self.ttl:
                    return obj
                del self.cache[key]
            obj = func(*args, **kwargs)
            if len(self.cache) >= self.maxsize:
                self.cache.popitem(last=False)
            self.cache[key] = (obj, self.timer())
            return obj
        return wrapper

