def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    if isinstance(params, dict):
        # Convert in-style named parameters to out-style parameters
        out_params = {f'${key}': value for key, value in params.items()}
    else:
        # Convert in-style ordinal parameters to out-style parameters
        out_params =list(params)

    # Replace in-style parameters in SQL query with out-style parameters
    formatted_sql = sql
    if isinstance(out_params, dict):
        for key, value in out_params.items():
            formatted_sql = formatted_sql.replace(f':{self.SQLParams.in_style}{key}', str(value))
    else:
        for i, value in enumerate(out_params):
            formatted_sql = formatted_sql.replace(f':{self.SQLParams.in_style}{i+1}', str(value))

    return formatted_sql, out_params

