) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    def format_param(params):
        if isinstance(params, Mapping):
            return {f":{key}": value for key, value in params.items()}
        elif isinstance(params, Sequence):
            return tuple(value for value in params)
        else:
            raise ValueError("params must be a Mapping or Sequence")

    if isinstance(many_params, Mapping):
        many_params = [many_params]

    formatted_sql = sql
    converted_params = [format_param(params) for params in many_params]

