def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::
        A & (A | B) = A, A | (A & B) = A

    Negative absorption::
        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3 and expr[1] in ['&', '|']:
            A, op, B = expr
            if op == '&':
                if isinstance(B, tuple) and B[1] == '|':
                    if B[0] == A:
                        result.append(A)
                    else:
                        result.append((A, '&', (B[0], '|', B[2])))
                elif isinstance(B, tuple) and B[1] == '&':
                    if B[0] == A:
                        result.append(A)
                    else:
                        result.append((A, '&', (B[0], '&', B[2])))
            elif op == '|':
                if isinstance(B, tuple) and B[1] == '&':
                    if B[0] == A:
                        result.append(A)
                    else:
                        result.append((A, '|', (B[0], '&', B[2])))
                elif isinstance(B, tuple) and B[1] == '|':
                    if B[0] == A:
                        result.append(A)
                    else:
                        result.append((A, '|', (B[0], '|', B[2])))
        else:
            result.append(expr)
    return result

