def next_version(version):
    parts = list(map(int, version.split('.')))
    while True:
        parts[-1] += 1
        for i in range(len(parts) - 1, 0, -1):
            if parts[i] > 9:
                parts[i] = 0
                parts[i - 1] += 1
            else:
