import datetime

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    try:
        num, unit = frequency.rsplit(None, 1)
        num = int(num)
        if unit == "seconds":
            return datetime.timedelta(seconds=num)
        elif unit == "minutes":
            return datetime.timedelta(minutes=num)
        elif unit == "hours":
            return datetime.timedelta(hours=num)
        elif unit == "days":
            return datetime.timedelta(days=num)
        elif unit == "weeks":
            return datetime.timedelta(weeks=num)
        elif unit == "months":
            return datetime.timedelta(days=num * 30)  # Approximation
        elif unit == "years":
            return datetime.timedelta(days=num * 365)  # Approximation
        else:
            raise ValueError(f"Unknown unit: {unit}")
    except Exception as e:
        raise ValueError("Invalid frequency format")

