import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]

    if verbose:
        print(f"Running command: {' '.join(commands + args)}")

    try:
        if hide_stderr:
            result = subprocess.run(commands + args, cwd=cwd, capture_output=True, text=True, check=True, env=env, stderr=subprocess.DEVNULL)
        else:
            result = subprocess.run(commands + args, cwd=cwd, capture_output=True, text=True, check=True, env=env)

        if verbose:
            print(f"Command output: {result.stdout}")
            if result.stderr:
                print(f"Command stderr: {result.stderr}")

        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}")
            print(f"Command stdout: {e.stdout}")
            print(f"Command stderr: {e.stderr}")
        raise e

