from datetime import datetime, time, timedelta, timezone

class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        midnight = datetime(1970, 1, 1, tzinfo=timezone.utc)
        time_obj = midnight + timedelta(microseconds=ticks // 1000)

        if tz:
            time_obj = time_obj.astimezone(tz)

        return cls.from_datetime(time_obj.time())

    @classmethod
    def from_datetime(cls, dt):
        return cls(dt.hour, dt.minute, dt.second, dt.microsecond)

    def __init__(self, hour, minute, second, microsecond):
        self.hour = hour
        self.minute = minute
        self.second = second
        self.microsecond = microsecond

    def __str__(self):
        return f"{self.hour:02d}:{self.minute:02d}:{self.second:02d}.{self.microsecond:06d}"

