def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    import ROOT
    from hep.root.hist import histogram, graph

    if make_value is None:
        make_value = lambda bin: bin

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) < 2:
        raise ValueError("field_names must have at least two elements")

    result = graph()

    for bin in hist:
        x, y = get_coordinate, make_value(bin)
        if scale is True:
            y *= hist.scale
        result.set_point(bin.idx, x, y)

    result.FieldNames = field_names

    return result

