def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate} does not provide {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names(True))
    required_attributes = set(iface.names(False))

    missing_methods = required_methods - candidate_methods
    undefined_attributes = required_attributes - candidate_methods

    if missing_methods or undefined_attributes:
        errors = []
        if missing_methods:
            errors.append(f"Missing methods: {', '.join(missing_methods)}")
        if undefined_attributes:
            errors.append(f"Undefined attributes: {', '.join(undefined_attributes)}")
        if len(errors) > 1:
            raise Invalid('\n'.join(errors))
        else:
            raise Invalid(errors[0])

    return True

