import zope.interface

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"{candidate} does not claim to provide {iface}")

    candidate_methods = set(dir(candidate.__class__))
    required_methods = set(iface.namesOfAllMethods())
    required_attributes = set(iface.namesOfAllAttributes())

    method_errors = [(method, f"{candidate} does not define method {method}") for method in required_methods if method not in candidate_methods]
    attribute_errors = [(attribute, f"{candidate} does not define attribute {attribute}") for attribute in required_attributes if attribute not in candidate_methods]

    errors = method_errors + attribute_errors

    if errors:
        if len(errors) == 1:
            raise errors[0][1]
        else:
            raise zope.interface.Invalid("Multiple errors found:\n" + "\n".join(f"- {error[1]}" for error in errors))

    return True

